package com.tuckersoft.branchengine.entity;
import jakarta.persistence.*; import lombok.*; import java.time.Instant; import java.util.*;
@Entity @Table(name="decisions") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder public class Decision { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) private Playthrough playthrough; @ManyToOne(optional=false) private StoryNode node; @Column(nullable=false,columnDefinition="TEXT") private String rawInput; @Column(nullable=false) private String branchType; @Column(nullable=false) private String impactLevel; @Column(nullable=false) private String handlerUnit; @Column(nullable=false) private String outcomeCode; private String resolvedNodeCode; @Column(nullable=false) private String status; @Column(nullable=false) private Instant createdAt; @Column(nullable=false) private Instant updatedAt; @OneToMany(mappedBy="decision") @Builder.Default private List<RealityLog> realityLogs=new ArrayList<>(); }
